import math
X=0.0;Y=0.0;PSI=0.0
grid={}
corners=[]
T=None
U=None
mode='rev'
fwd_start=None
prev_touch=0
n=0
woke_end=False
L1=2.75;CH=1.05;L2=2.6

def wrap(a):
    while a>math.pi: a-=2*math.pi
    while a<-math.pi: a+=2*math.pi
    return a

def tow(px,py):
    c=math.cos(PSI);s=math.sin(PSI)
    return (X+px*c-py*s, Y+px*s+py*c)

def clamp(x,a):
    return max(-a,min(a,x))

def steer_for(h,hd,K=2.0):
    r=math.radians(hd)
    ff=math.degrees(math.atan(L1*math.sin(r)/(L2+CH*math.cos(r))))
    return clamp(ff+K*(h-hd),34.0)

def bay_axis():
    cs=[c for c in corners if c[2]>=2.0]
    cs.sort(key=lambda c:-c[2])
    cs=cs[:4]
    if len(cs)<4: return None
    cx=sum(c[0] for c in cs)/4.0;cy=sum(c[1] for c in cs)/4.0
    cs.sort(key=lambda c:math.atan2(c[1]-cy,c[0]-cx))
    e=[(cs[(i+1)%4][0]-cs[i][0],cs[(i+1)%4][1]-cs[i][1]) for i in range(4)]
    l=[math.hypot(*x) for x in e]
    if min(l)<1.0: return None
    a0=(l[0]+l[2]);a1=(l[1]+l[3])
    if a0>=a1: ex,ey=e[0][0]-e[2][0],e[0][1]-e[2][1]
    else: ex,ey=e[1][0]-e[3][0],e[1][1]-e[3][1]
    nn=math.hypot(ex,ey)
    if nn<1e-6: return None
    return (cx,cy,ex/nn,ey/nn)

def core(obs):
    global X,Y,PSI,T,U,mode,fwd_start,prev_touch,n,woke_end
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    m=obs.get('motion') or {}
    v=m.get('v_mps',0.0) or 0.0
    st=math.radians(obs.get('steer_deg',0.0) or 0.0)
    w=v/L1*math.tan(st)
    pm=PSI+0.5*w*dt
    X+=v*math.cos(pm)*dt;Y+=v*math.sin(pm)*dt;PSI+=w*dt
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin') or [0,0]
        for p in (vw.get('walls') or []):
            try:
                b=math.radians(p[0]);d=float(p[1])
            except Exception: continue
            if d>12.0: continue
            wx,wy=tow(o[0]+d*math.cos(b),o[1]+d*math.sin(b))
            grid[(int(math.floor(wx/0.3)),int(math.floor(wy/0.3)))]=(wx,wy)
        for p in (vw.get('target_corners') or []):
            try:
                b=math.radians(p[0]);d=float(p[1])
            except Exception: continue
            wx,wy=tow(o[0]+d*math.cos(b),o[1]+d*math.sin(b))
            wt=1.0/(0.3+d)**2*4.0
            best=None;bd=1.0
            for c in corners:
                dd=math.hypot(c[0]-wx,c[1]-wy)
                if dd<bd: bd=dd;best=c
            if best is None:
                corners.append([wx,wy,1.0,wt])
            else:
                W=best[3]+wt
                best[0]=(best[0]*best[3]+wx*wt)/W;best[1]=(best[1]*best[3]+wy*wt)/W
                best[3]=W;best[2]+=1.0
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        wx,wy=tow(1.62+d*math.cos(b),0.41+d*math.sin(b))
        if T is None: T=[wx,wy]
        else:
            T[0]=0.8*T[0]+0.2*wx;T[1]=0.8*T[1]+0.2*wy
    rig=obs.get('rig') or {}
    h=obs.get('hitch_deg',0.0) or 0.0
    rr=rig.get('trailer_rear') or [-4.55,0.0]
    R=tow(rr[0],rr[1])
    psit=PSI+math.radians(rig.get('trailer_heading_deg',-h))
    status=obs.get('status','')
    touches=(obs.get('counters') or {}).get('touches',0)
    look=-23.0
    if touches>prev_touch:
        prev_touch=touches
        mode='fwd';fwd_start=(X,Y)
    if status=='JACKKNIFED' or abs(h)>48.0:
        if mode!='fwd':
            mode='fwd';fwd_start=(X,Y)
    if mode=='fwd':
        dist=math.hypot(X-fwd_start[0],Y-fwd_start[1])
        if abs(h)<6.0 and dist>1.0:
            mode='rev'
        else:
            return (clamp(-0.8*h,34.0),1.2,look)
    back=psit+math.pi
    bay=bay_axis()
    alpha=None;spd=-1.0;inbay=False
    if bay is not None:
        cx,cy,ux,uy=bay
        if U is None:
            if (cx-R[0])*ux+(cy-R[1])*uy<0: ux,uy=-ux,-uy
            U=(ux,uy)
        else:
            if ux*U[0]+uy*U[1]<0: ux,uy=-ux,-uy
            U=(ux,uy)
        dC=math.hypot(cx-R[0],cy-R[1])
        if dC<11.0:
            inbay=True
            rx,ry=R[0]-cx,R[1]-cy
            elat=ux*ry-uy*rx
            tcx=R[0]+1.45*math.cos(psit);tcy=R[1]+1.45*math.sin(psit)
            along=(tcx-cx)*ux+(tcy-cy)*uy
            togo=-along
            la=max(2.0,0.8*abs(togo)+1.5)
            dev=clamp(-math.atan2(elat,la),math.radians(35))
            alpha=math.atan2(uy,ux)+dev
            if togo<4.0: spd=-0.5
            if along>0.5:
                if not woke_end:
                    woke_end=True
                    try: wake('past bay centre, stopping')
                    except Exception: pass
                return (steer_for(h,0.0),0.0,look)
    if alpha is None:
        near=[(qx-R[0],qy-R[1]) for (qx,qy) in grid.values() if abs(qx-R[0])<10 and abs(qy-R[1])<10]
        best=None;bs=-1e9
        tdir=None
        if T is not None: tdir=math.atan2(T[1]-R[1],T[0]-R[0])
        for k in range(-14,15):
            a=back+math.radians(5*k)
            ca=math.cos(a);sa=math.sin(a)
            ax,ay=3.5*ca,3.5*sa
            free=8.0;clr=1.8
            for (px,py) in near:
                al=px*ca+py*sa
                if al>0:
                    lt=abs(-px*sa+py*ca)
                    if lt<1.0 and al<free: free=al
                dd=math.hypot(px-ax,py-ay)
                if dd<clr: clr=dd
            sc=3.0*clr+0.4*free-0.015*abs(5*k)
            if free<2.0: sc-=5.0
            if tdir is not None: sc-=0.02*abs(math.degrees(wrap(a-tdir)))
            if sc>bs: bs=sc;best=a
        alpha=best
    D=math.degrees(wrap(alpha+math.pi-psit))
    lim=20.0 if inbay else 30.0
    hd=clamp(-1.0*D,lim)
    s=steer_for(h,hd)
    if abs(h-hd)>15.0: spd=max(spd,-0.7)
    if n%20==0:
        print('t=%.1f h=%.1f hd=%.1f D=%.1f bay=%s corners=%d T=%s'%(obs.get('t',0),h,hd,D,inbay,len(corners),T is not None))
    return (s,spd,look)

def control(obs):
    try:
        return core(obs)
    except Exception as e:
        print('ERR',e)
        h=obs.get('hitch_deg',0.0) or 0.0
        return (steer_for(h,0.0),-0.6,-23.0)

