import math
L1=2.75;CH=1.05;L2=2.6
PSI=0.0
mode='fwd'
fd=0.0
rd=0.0
TB=None
HT=None
t0=None
woke=False
n=0
def clamp(x,a):
    return max(-a,min(a,x))
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def steer_for(h,hd,K=1.6):
    r=math.radians(hd)
    ff=math.degrees(math.atan(L1*math.sin(r)/(L2+CH*math.cos(r))))
    return clamp(ff+K*(h-hd),34.0)
def core(obs):
    global PSI,mode,fd,rd,TB,HT,t0,woke,n
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    m=obs.get('motion') or {}
    v=m.get('v_mps',0.0) or 0.0
    st=math.radians(obs.get('steer_deg',0.0) or 0.0)
    PSI+=math.degrees(v/L1*math.tan(st)*dt)
    h=obs.get('hitch_deg',0.0) or 0.0
    back=PSI-h+180.0
    touches=(obs.get('counters') or {}).get('touches',0)
    if t0 is None:
        t0=touches
        TB=back-10.0
        HT=TB-180.0
    if touches>t0:
        if not woke:
            woke=True
            try: wake('touched again')
            except Exception: pass
        return (0.0,0.0,-23.0)
    if mode=='fwd':
        if v>0: fd+=v*dt
        tf=back-180.0
        if (fd>3.0 and abs(wrap(tf-HT))<3.0) or fd>4.5:
            mode='rev'
        else:
            s=clamp(2.0*wrap(HT-PSI),15.0)
            if n%10==0: print('F fd=%.1f psi=%.1f tf=%.1f HT=%.1f'%(fd,PSI,tf,HT))
            return (s,1.0,0.0)
    if v<0: rd+=-v*dt
    e=wrap(TB-back)
    hd=clamp(-1.2*e,10.0)
    s=steer_for(h,hd)
    if rd>6.0:
        if not woke:
            woke=True
            try: wake('reversed 6m without finish')
            except Exception: pass
        return (s,0.0,-23.0)
    if n%10==0: print('R rd=%.1f h=%.1f e=%.1f'%(rd,h,e))
    return (s,-0.4,-23.0)
def control(obs):
    try:
        return core(obs)
    except Exception as ex:
        print('ERR',ex)
        return (0.0,0.0,-23.0)

