        ds=max(0.0,xr-aa,aa-vf);dlat=max(0.0,abs(bb)-hw)
        if math.hypot(ds,dlat)<0.1: mdg=(aa,bb);break
    if t-st['lp']>2.0:
        st['lp']=t
        print('t%.1f %s phi%.0f pose(%.2f,%.2f,%.0f) p(%.2f,%.2f) b(%.2f,%.2f) n%d %s %s'%(t,st['ph'],phi,pose[0],pose[1],math.degrees(pose[2]),px,py,st['bx'],st['by'],len(pts),danger,mdg))
    if st['ph']=='fwd':
        x,y,h=pose
        if mdg is not None and mdg[0]>0.0:
            if st['w']<3: st['w']+=1;wake('fwd danger mower %.1f %.1f'%mdg)
            return {'steer_deg':obs['steer_deg'],'speed_mps':0.0,'look_deg':0.0}
        if (st['fd']>1.3 and abs(phi)<8 and abs(h)<0.12) or st['fd']>2.4:
            st['ph']='rev';st['P']=[(px,py)]
        else:
            hdes=clip(1.0*(-0.35-y),-0.35,0.35)
            steer=clip(math.degrees(2.5*(hdes-h)),-35,35)
            return {'steer_deg':steer,'speed_mps':0.4,'look_deg':0.0}
    if st['ph']=='pf':
