SEED='-3.2,-4.2 -3.2,-4.0 -2.9,-3.9 -2.8,-3.8 -2.8,-3.7 -2.5,-3.4 -2.4,-3.3 -2.3,-3.3 -2.2,-3.3 -2.1,-3.1 -2.0,-3.0 -1.8,-3.0 -1.7,-2.9 -1.6,-3.0 -1.6,1.0 -1.5,-3.0 -1.4,-2.6 -1.4,1.1 -1.3,-2.9 -1.3,1.1 -1.1,-2.9 -1.1,1.1 -0.9,1.1 -0.8,1.1 -0.7,-2.9 -0.6,-2.9 -0.6,1.0 -0.5,-2.9 -0.4,1.1 -0.3,-3.0 -0.3,1.0 -0.1,-3.0 -0.1,1.0 0.1,-3.2 0.2,1.0 0.4,-3.2 0.4,0.9'
M={}
for _s in SEED.split():
    _a,_b=_s.split(',');_x=float(_a);_y=float(_b)
    M[('s',_x,_y)]=(_x,_y,1e9)
pose=[2.62,-0.60,math.radians(-11.0)]
st={'ph':'rev','fd':0.0,'lp':-9.0,'w':0,'t0':None,'P':None,'bx':-6.9,'by':-6.65,'pst':0.0}
L1=1.25
DX,DY=-0.73,-0.68
def wrap(a):
    return (a+180.0)%360.0-180.0
def v2w(x,y):
    th=pose[2];c,s=math.cos(th),math.sin(th)
    return pose[0]+c*x-s*y, pose[1]+s*x+c*y
def w2v(x,y):
    th=pose[2];c,s=math.cos(th),math.sin(th)
    dx,dy=x-pose[0],y-pose[1]
    return c*dx+s*dy, -s*dx+c*dy
def tow(o,b,d):
    x0,y0=v2w(o[0],o[1])
    a=math.radians(b)+pose[2]
    return x0+d*math.cos(a), y0+d*math.sin(a)
def clip(v,a,b):
    return max(a,min(b,v))
def path():
    bx,by=st['bx'],st['by']
    return st['P']+[(-0.6,-0.6),(-1.3,-1.2),(bx,by),(bx+DX*2.5,by+DY*2.5)]
def lookpt(px,py,la):
    P=path()
    best=None;acc=0.0;segs=[]
    for i in range(len(P)-1):
        x0,y0=P[i];x1,y1=P[i+1];dx,dy=x1-x0,y1-y0;L=max(1e-3,math.hypot(dx,dy))
        segs.append((x0,y0,dx/L,dy/L,L,acc))
        u=clip(((px-x0)*dx+(py-y0)*dy)/(L*L),0.0,1.0)
        qx,qy=x0+u*dx,y0+u*dy;dd=math.hypot(px-qx,py-qy)
        if best is None or dd<best[0]-0.05: best=(dd,acc+u*L)
        acc+=L
    s=best[1]+la
    for x0,y0,ux,uy,L,a0 in segs:
        if s<=a0+L: return x0+ux*(s-a0),y0+uy*(s-a0)
    x0,y0,ux,uy,L,a0=segs[-1]
    return x0+ux*(s-a0),y0+uy*(s-a0)
def control(obs):
    t=obs['t'];dt=obs.get('dt',0.1) or 0.1
    if st['t0'] is None: st['t0']=t
    v=obs['motion']['v_mps'];dl=math.radians(obs['steer_deg'])
    th=pose[2]
    pose[0]+=v*math.cos(th)*dt;pose[1]+=v*math.sin(th)*dt;pose[2]+=v*math.tan(dl)/L1*dt
    if st['ph']=='pf': st['fd']+=abs(v)*dt
    views=obs.get('views') or {}
    for k,vw in views.items():
        try:
            o=vw['origin']
            for b,d in vw.get('walls',[]):
                if k=='periphery' and d>3.0: continue
                if d>6.0: continue
                x,y=tow(o,b,d)
                M[(int(round(x*10)),int(round(y*10)))]=(x,y,t)
        except Exception:
            pass
    if int(round(t*10))%10==0:
        for kk in [kk for kk,p in M.items() if p[2]<1e8 and t-p[2]>15]: del M[kk]
    tg=obs.get('target') or {}
    try:
        if tg.get('in_sight') and tg.get('dist_m') is not None and tg['dist_m']<8:
            bx,by=tow(obs['rig']['eye'],tg['bearing_deg'],tg['dist_m'])
            if math.hypot(bx-st['bx'],by-st['by'])<2.5:
                k=0.08 if tg['dist_m']<4 else 0.04
                st['bx']+=k*(bx-st['bx']);st['by']+=k*(by-st['by'])
    except Exception:
        pass
    rig=obs['rig'];phi=obs['hitch_deg']
    tr=rig['trailer_rear'];px,py=v2w(tr[0],tr[1])
    if st['P'] is None: st['P']=[(px,py)]
    psi=pose[2]+math.radians(rig['trailer_heading_deg'])
    bcur=psi+math.pi
    pts=[(p[0],p[1]) for p in M.values() if (p[0]-px)**2+(p[1]-py)**2<30]
    fresh=[(p[0],p[1]) for p in M.values() if p[2]<1e8 and t-p[2]<5.0]
    danger=None
    ux,uy=math.cos(psi),math.sin(psi)
    for x,y in pts:
        rx,ry=x-px,y-py
        s=rx*ux+ry*uy;l=abs(-rx*uy+ry*ux)
        ds=max(0.0,-s,s-1.0);dlat=max(0.0,l-0.475)
        if math.hypot(ds,dlat)<0.06 and s<0.5: danger='trailer %.1f %.1f'%(x,y);break
    vf=rig.get('vehicle_front');hw=rig.get('vehicle_half_width',0.525)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    if vf is None: vf=1.55
    xr=vf-1.8;mdmin=9.0;mside=0.0
    for x,y in fresh:
        aa,bb=w2v(x,y)
        if aa<0.3: continue
        ds=max(0.0,xr-aa,aa-vf);dlat=max(0.0,abs(bb)-hw)
        dd=math.hypot(ds,dlat)
        if dd<mdmin: mdmin=dd;mside=1.0 if bb>0 else -1.0
    lx,ly=lookpt(px,py,1.1)
    a=math.atan2(ly-py,lx-px)
    e=wrap(math.degrees(a-bcur))
    rel=wrap(math.degrees(bcur-pose[2]))
    cyc=(t-st['t0'])%4.0
    look=clip(rel,-165,165) if cyc<2.8 else 40.0
    if t-st['lp']>2.0:
        st['lp']=t
        print('t%.1f %s phi%.0f pose(%.2f,%.2f,%.0f) p(%.2f,%.2f) e%.0f b(%.2f,%.2f) md%.2f%+d %s'%(t,st['ph'],phi,pose[0],pose[1],math.degrees(pose[2]),px,py,e,st['bx'],st['by'],mdmin,mside,danger))
    if st['ph']=='pf':
        if st['fd']>=0.5: st['ph']='rev'
        else: return {'steer_deg':st['pst'],'speed_mps':0.35,'look_deg':30.0}
    if danger is not None:
        if st['w']<4: st['w']+=1;wake('rev danger %s'%danger)
        return {'steer_deg':obs['steer_deg'],'speed_mps':0.0,'look_deg':look}
    past=(px-st['bx'])*DX+(py-st['by'])*DY
    if past>2.0:
        if st['w']<6: st['w']=6;wake('past expected bay, stopped')
        return {'steer_deg':0.0,'speed_mps':0.0,'look_deg':look}
    if abs(phi)>50:
        st['ph']='pf';st['fd']=0.0;st['pst']=0.0
        return {'steer_deg':0.0,'speed_mps':0.0,'look_deg':look}
    if mdmin<0.03:
        st['ph']='pf';st['fd']=0.0;st['pst']=-30.0*mside
        if st['w']<5: st['w']+=1;wake('mower nose at rail, pulling off')
        return {'steer_deg':st['pst'],'speed_mps':0.0,'look_deg':look}
    phd=clip(-1.3*e,-40,40)
    r=math.radians(phd)
    ff=math.degrees(math.atan(L1*math.sin(r)/(0.85+0.3*math.cos(r))))
    steer=clip(ff+3.0*(phi-phd),-45,45)
    if mdmin<0.15 and abs(phi)<38:
        steer=clip(steer+mside*25.0*(0.15-mdmin)/0.15+mside*8.0,-45,45)
    sp=-0.3 if abs(phi-phd)<12 and mdmin>0.2 else -0.18
    return {'steer_deg':steer,'speed_mps':sp,'look_deg':look}

