import math
phis = 0.0
mode = 'rev'
n = 0
def clamp(v,a,b):
    return max(a,min(b,v))
def control(obs):
    global phis, mode, n
    n += 1
    h = obs['hitch_deg']
    rig = obs['rig']
    tr = rig['trailer_rear']
    th = rig['trailer_heading_deg']
    hw = rig.get('trailer_half_width', 1.3)
    back = math.radians(th + 180.0)
    cb, sb = math.cos(back), math.sin(back)
    views = obs.get('views') or {}
    cam = views.get('camera')
    def tf(o, b, d):
        px = o[0] + d*math.cos(math.radians(b)); py = o[1] + d*math.sin(math.radians(b))
        dx = px - tr[0]; dy = py - tr[1]
        return (dx*cb + dy*sb, -dx*sb + dy*cb)
    if mode == 'fwd':
        if abs(h) < 10:
            mode = 'rev'
        return (0.0, 1.5, -41)
    if abs(h) > 45:
        mode = 'fwd'
        return (0.0, 1.5, -41)
    if cam:
        o = cam['origin']
        pts = [tf(o, b, d) for b, d in cam.get('walls', [])]
        pts = [p for p in pts if p[0] > -1.0]
        frees = []
        for phi in range(-70, 71, 2):
            c = math.cos(math.radians(phi)); s = math.sin(math.radians(phi))
            f = 15.0
            for x, y in pts:
                xr = x*c + y*s; yr = -x*s + y*c
                if xr > 0 and abs(yr) < hw + 0.4:
                    f = min(f, xr)
            frees.append((phi, f))
        mx = max(f for _, f in frees)
        best = None; run = []; runs = []
        for phi, f in frees:
            if f >= mx - 0.5:
                run.append(phi)
            else:
                if run: runs.append(run)
                run = []
        if run: runs.append(run)
        runs.sort(key=lambda r: (len(r), -abs(sum(r)/len(r))), reverse=True)
        phi = sum(runs[0]) / len(runs[0])
        L = [y for x, y in pts if -2 < x < 4 and y > 0]
        R = [y for x, y in pts if -2 < x < 4 and y < 0]
        if L and R:
            cc = (min(L) + max(R)) / 2.0
            phi += clamp(4.0*cc, -10, 10)
        corners = cam.get('target_corners') or []
        if len(corners) >= 2:
            cp = [tf(o, b, d) for b, d in corners]
            cx = sum(p[0] for p in cp)/len(cp); cy = sum(p[1] for p in cp)/len(cp)
            if cx > 0.5 and math.hypot(cx, cy) < 13:
                pb = math.degrees(math.atan2(cy, cx))
                if abs(pb) < 45:
                    phi = pb
        phi = clamp(phi, -60, 60)
        phis += 0.12 * (phi - phis)
    hdes = clamp(0.6 * phis, -28, 28)
    steer = 0.4 * hdes + 2.0 * (h - hdes)
    steer = clamp(steer, -42, 42)
    tgt = obs.get('target') or {}
    sp = -1.0
    if tgt.get('in_sight') and tgt.get('dist_m') is not None and tgt['dist_m'] < 8:
        sp = -0.8
    if n % 50 == 0:
        print('t=%.1f h=%.1f phis=%.1f hdes=%.1f st=%.1f prog=%s' % (obs['t'], h, phis, hdes, steer, obs['progress'].get('covered')))
    return (steer, sp, -41)

