    vhw=rig.get('vehicle_half_width') or 1.275
    vf=rig.get('vehicle_front',4.9)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    try: vf=float(vf)
    except Exception: vf=4.9
    rem=obs['progress'].get('remaining',99)
    views=obs.get('views') or {}
    c=math.cos(PSI);s=math.sin(PSI)
    for k,vw in views.items():
        o=vw['origin']
        for b,d in vw.get('walls',[]):
            px=o[0]+d*math.cos(math.radians(b));py=o[1]+d*math.sin(math.radians(b))
            mem.append((t,k,X+px*c-py*s,Y+px*s+py*c))
    mem=[m for m in mem if t-m[0]<3.0][-800:]
    ux=hi[0]-tr[0];uy=hi[1]-tr[1];Ln=math.hypot(ux,uy) or 1.0
    ux/=Ln;uy/=Ln
    tcx=tr[0]+6.75*ux;tcy=tr[1]+6.75*uy
    ccx=vf-3.1
    clc=99.0;clt=99.0;ta=0.0;tb=0.0;cb_=0.0;cf=99.0
    for (tt,k,wx,wy) in mem:
        dx=wx-X;dy=wy-Y
        px=dx*c+dy*s;py=-dx*s+dy*c
        dc,a1,b1=rd(px,py,ccx,0.0,1.0,0.0,3.1,vhw)
        dtr,a2,b2=rd(px,py,tcx,tcy,ux,uy,6.75,hw)
        if dc<clc: clc=dc;cb_=b1
        if a1>1.5 and dc<cf: cf=dc
        if dtr<clt: clt=dtr;ta=a2;tb=b2
    cl=min(clc,clt)
    if mode=='HOLD':
        return (0.0,0.0,110)
    nr+=1
    if abs(h)>45:
        mode='HOLD';dowake('hitch %.1f too big, stopped'%h)
        return (0.0,0.0,-41)
    thr=0.08
    if cl<thr and nr>8:
        mode='HOLD';dowake('clearance %.2f (cab %.2f cf %.2f trailer %.2f a=%.1f b=%.1f) stopped h=%.1f rem=%.1f'%(cl,clc,cf,clt,ta,tb,h,rem))
        return (0.0,0.0,110)
    cam=views.get('camera')
    if cam:
        back=math.radians(th+180.0);cb=math.cos(back);sb=math.sin(back)
        o=cam['origin']
        def tf(b,d):
            px=o[0]+d*math.cos(math.radians(b));py=o[1]+d*math.sin(math.radians(b))
            dx=px-tr[0];dy=py-tr[1]
            return (dx*cb+dy*sb,-dx*sb+dy*cb)
        pts=[tf(b,d) for b,d in cam.get('walls',[])]
        pts=[p for p in pts if p[0]>-1.0]
        frees=[]
        for ph in range(-70,71,2):
            cc_=math.cos(math.radians(ph));ss=math.sin(math.radians(ph))
            f=15.0
            for x,y in pts:
                xr=x*cc_+y*ss;yr=-x*ss+y*cc_
                if xr>0 and abs(yr)<hw+0.4: f=min(f,xr)
            frees.append((ph,f))
        mx=max(f for _,f in frees)
        run=[];runs=[]
        for ph,f in frees:
            if f>=mx-0.5: run.append(ph)
            else:
                if run: runs.append(run)
                run=[]
        if run: runs.append(run)
        runs.sort(key=lambda r:(len(r),-abs(sum(r)/len(r))),reverse=True)
        phi=sum(runs[0])/len(runs[0])
        L=[y for x,y in pts if -2<x<4 and y>0]
        R=[y for x,y in pts if -2<x<4 and y<0]
        if L and R:
            phi+=clamp(4.0*(min(L)+max(R))/2.0,-10,10)
        elif L and min(L)<hw+1.5: phi-=8
        elif R and max(R)>-(hw+1.5): phi+=8
        corners=cam.get('target_corners') or []
        if len(corners)>=2:
            cp=[tf(b,d) for b,d in corners]
            cx=sum(p[0] for p in cp)/len(cp);cy=sum(p[1] for p in cp)/len(cp)
            if cx>0.5 and math.hypot(cx,cy)<13:
                pb=math.degrees(math.atan2(cy,cx))
                if abs(pb)<30: phi=pb
        phi=clamp(phi,-50,50)
        phis+=0.1*(phi-phis)
    hdes=clamp(-0.6*phis,-30,30)
    steer=0.4*hdes+2.0*(h-hdes)
    lc=99.0
    if tb>0 and ta>0: lc=min(lc,clt)
    if cb_>0: lc=min(lc,clc)
    if lc<0.8:
        steer=min(steer,0.0)-40.0*(0.8-lc)
    rc=99.0
    if tb<0 and ta>0: rc=min(rc,clt)
    if cb_<0: rc=min(rc,clc)
    if rc<0.6:
        steer=max(steer,0.0)+30.0*(0.6-rc)
    if cf<0.5: steer=clamp(steer,-8,42)
    steer=clamp(steer,-42,42)
    sp=-0.7
    if cl<1.0: sp=-0.35
    tgt=obs.get('target') or {}
    if tgt.get('in_sight') and tgt.get('dist_m') is not None and tgt['dist_m']<8: sp=max(sp,-0.6)
    look=-41
    k=nr%30
    if rem>8 and abs(h)>8 and k<9: look=110
    if n%20==0:
        print('t=%.1f h=%.1f phis=%.1f hdes=%.1f st=%.1f cl=%.2f(c%.2f cf%.2f t%.2f a%.1f b%.1f) lc=%.2f rem=%.1f'%(t,h,phis,hdes,steer,cl,clc,cf,clt,ta,tb,lc,rem))
    return (steer,sp,look)
